// жадно: самая крупная, что влезает
int Greedy(int[] coins, int amount) {
    Array.Sort(coins);
    int count = 0;
    for (int i = coins.Length - 1; i >= 0; i--)
        while (amount >= coins[i]) { amount -= coins[i]; count++; }
    return amount == 0 ? count : -1;
}

