public int Change(int amount, int[] coins) {
    var dp = new int[amount + 1];
    dp[0] = 1;                                 // ничего не брать
    foreach (int c in coins)                   // снаружи — монеты: наборы
        for (int s = c; s <= amount; s++)      // по возрастанию: c можно повторять
            dp[s] += dp[s - c];
    return dp[amount];
}

